const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define the area of interest for Bobiri Forest Reserve, Ghana.
  const aoi = ee.Geometry.Polygon([[
    [-1.385, 6.721], [-1.385, 6.621], [-1.305, 6.621], [-1.305, 6.721], [-1.385, 6.721]
  ]]);

  // 2. Data Acquisition
  // Use the Hansen Global Forest Change dataset for a direct measure of forest cover and loss.
  const hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

  // 3. Processing
  // Define "forest" as areas with tree cover greater than 30% in the year 2000.
  const treeCoverThreshold = 30;

  // Image for initial forest cover in 2000.
  const treeCover2000 = hansen.select('treecover2000');
  const forest2000 = treeCover2000.gt(treeCoverThreshold).selfMask();

  // Image for forest loss between 2001 and 2023 (inclusive).
  const loss = hansen.select('loss');
  const lossYear = hansen.select('lossyear');
  // Loss is coded from 1 (2001) to 23 (2023). We want all loss within this period.
  const forestLoss2003_2023 = loss.and(lossYear.gte(3)).and(lossYear.lte(23)).selfMask();

  // 4. Calculation
  // Calculate the area in square kilometers for each class.
  const pixelArea = ee.Image.pixelArea(); // Area in square meters
  const scale = 30; // Native resolution of Hansen dataset

  const reduceArea = (image) => {
    const area = image.multiply(pixelArea).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
    });
    return ee.Number(area.values().get(0)).divide(1e6); // Convert m^2 to km^2
  };

  const initialForestArea = reduceArea(forest2000);
  const lostForestArea = reduceArea(forestLoss2003_2023);

  // Retrieve the results.
  const initialAreaSqKm = initialForestArea.getInfo();
  const lostAreaSqKm = lostForestArea.getInfo();

  // 5. Validation & Final Answer
  if (initialAreaSqKm === null || lostAreaSqKm === null) {
    console.log("Calculation failed: Could not retrieve area values.");
    console.log("C3");
    return;
  }

  if (initialAreaSqKm === 0) {
      console.log("No initial forest cover found in the area for the year 2000.");
      console.log("C2");
      return;
  }

  const declinePercentage = (lostAreaSqKm / initialAreaSqKm) * 100;

  console.log(`Initial forest area (2000, >30% cover): ${initialAreaSqKm.toFixed(2)} sq km`);
  console.log(`Forest area lost (2003-2023): ${lostAreaSqKm.toFixed(2)} sq km`);
  console.log(`Decline relative to initial cover: ${declinePercentage.toFixed(2)}%`);

  // The question asks if cover declined. Any loss greater than zero confirms this.
  if (lostAreaSqKm > 0) {
    console.log("Evidence of forest loss found between 2003 and 2023.");
    console.log("A");
  } else {
    console.log("No evidence of forest loss found between 2003 and 2023.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
